import { BufferAttribute, BufferGeometry, Matrix4, Quaternion, Vector3 } from "three";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import dentitionUrl from "../../../assets/models/dentition.bin?url";

// The mouth is generated by scripts/dental-model/bake.mjs, in mm. The file is
// a 4-byte length, a JSON table and Meshopt-encoded streams: per mesh, int16
// positions, int8 normals, 8-bit colours (with ambient occlusion baked in)
// and 32-bit indices.

const decodeVertices = (bytes, slice, count, size) => {
  const out = new Uint8Array(count * size);
  MeshoptDecoder.decodeVertexBuffer(out, count, size, bytes.subarray(slice[0], slice[0] + slice[1]));
  return out;
};

const buildGeometry = (bytes, mesh) => {
  const { count, indexCount, min, scale } = mesh;
  const raw = decodeVertices(bytes, mesh.position, count, 8);
  const quantized = new Int16Array(raw.buffer);
  const position = new Float32Array(count * 3);
  for (let v = 0; v < count; v += 1) {
    for (let c = 0; c < 3; c += 1) {
      position[v * 3 + c] = (quantized[v * 4 + c] + 32767) * scale + min[c];
    }
  }
  const normalRaw = new Int8Array(decodeVertices(bytes, mesh.normal, count, 4).buffer);
  const normal = new Float32Array(count * 3);
  const colorRaw = decodeVertices(bytes, mesh.color, count, 4);
  const color = new Float32Array(count * 3);
  for (let v = 0; v < count; v += 1) {
    for (let c = 0; c < 3; c += 1) {
      normal[v * 3 + c] = normalRaw[v * 4 + c] / 127;
      color[v * 3 + c] = colorRaw[v * 4 + c] / 255;
    }
  }
  const indices = new Uint32Array(indexCount);
  MeshoptDecoder.decodeIndexBuffer(
    new Uint8Array(indices.buffer),
    indexCount,
    4,
    bytes.subarray(mesh.index[0], mesh.index[0] + mesh.index[1]),
  );
  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new BufferAttribute(position, 3));
  geometry.setAttribute("normal", new BufferAttribute(normal, 3));
  geometry.setAttribute("color", new BufferAttribute(color, 3));
  geometry.setIndex(new BufferAttribute(indices, 1));
  geometry.computeBoundingSphere();
  return geometry;
};

// Stored for the left side, as three columns; the right is its mirror image.
const placement = (tooth, right) => {
  const r = tooth.rotation;
  const flip = tooth.flipY ? -1 : 1;
  const matrix = new Matrix4().set(
    r[0], r[1] * flip, r[2], tooth.center[0],
    r[3], r[4] * flip, r[5], tooth.center[1],
    r[6], r[7] * flip, r[8], tooth.center[2],
    0, 0, 0, 1,
  );
  if (right) matrix.premultiply(new Matrix4().makeScale(-1, 1, 1));
  return matrix;
};

const decompose = (matrix) => {
  const position = new Vector3();
  const quaternion = new Quaternion();
  const scale = new Vector3();
  matrix.decompose(position, quaternion, scale);
  return { position, quaternion, scale };
};

// Loaded once per page and shared by every 3D view. The geometry must not be
// disposed by a view that unmounts.
let pending;

export const loadDentition = () => {
  pending ??= fetch(dentitionUrl)
    .then((res) => {
      if (!res.ok) throw new Error("Could not load the dental model");
      return res.arrayBuffer();
    })
    .then(async (buffer) => {
      await MeshoptDecoder.ready;
      const jsonLength = new Uint32Array(buffer, 0, 1)[0];
      const header = JSON.parse(new TextDecoder().decode(new Uint8Array(buffer, 4, jsonLength)));
      const start = 4 + jsonLength + ((4 - (jsonLength % 4)) % 4);
      const bytes = new Uint8Array(buffer, start);
      const parts = Object.fromEntries(
        header.meshes.map((m) => [m.name, buildGeometry(bytes, m)]),
      );
      const teeth = [];
      header.teeth.forEach((tooth) => {
        const quadrant = tooth.fdi - (tooth.fdi % 10);
        const position = tooth.fdi % 10;
        const rightDigit = quadrant === 20 ? 1 : 4;
        [
          [tooth.fdi, false],
          [rightDigit * 10 + position, true],
        ].forEach(([fdi, right]) => {
          const matrix = placement(tooth, right);
          teeth.push({
            id: String(fdi),
            type: tooth.type,
            jaw: tooth.jaw,
            right,
            size: tooth.size,
            matrix,
            ...decompose(matrix),
          });
        });
      });
      return { parts, teeth, hinge: header.hinge };
    });
  return pending;
};
